const svg=$('#score-svg'), out=$('#score-out'), w1Sl=$('#sc-w1'), w1L=$('#sc-w1-lbl'), sgSl=$('#sc-sig'), sgL=$('#sc-sig-lbl');
const W=640,H=360, padL=48,padR=20;
// two fixed mixture means; weights and component std come from sliders
const mu=[-1.6,1.8];
const A=-6,B=6;
// top panel: density p(x); bottom panel: score s(x)=p'(x)/p(x)
const tp={x0:padL,x1:W-padR,y0:168,y1:24};
const bp={x0:padL,x1:W-padR,y0:H-30,y1:206};
const PX=x=>tp.x0+(x-A)/(B-A)*(tp.x1-tp.x0);
function comp(x,m,s){ return Math.exp(-(x-m)*(x-m)/(2*s*s))/(s*Math.sqrt(2*Math.PI)); }
function dens(x,w1,s){ return w1*comp(x,mu[0],s)+(1-w1)*comp(x,mu[1],s); }
function dcomp(x,m,s){ return -(x-m)/(s*s)*comp(x,m,s); }   // d/dx of one Gaussian
function ddens(x,w1,s){ return w1*dcomp(x,mu[0],s)+(1-w1)*dcomp(x,mu[1],s); }
function score(x,w1,s){ const p=dens(x,w1,s); return p>1e-9 ? ddens(x,w1,s)/p : 0; }
function render(){
  svg.innerHTML='';
  const w1=+w1Sl.value, s=+sgSl.value; w1L.textContent='w = '+w1.toFixed(2); sgL.textContent='σ = '+s.toFixed(1);
  // sample the curves
  const N=300; let pmax=1e-6, smax=1e-6;
  const xs=[], ps=[], ss=[];
  for(let i=0;i<=N;i++){ const x=A+(B-A)*i/N; const p=dens(x,w1,s), sc=score(x,w1,s);
    xs.push(x); ps.push(p); ss.push(sc); pmax=Math.max(pmax,p); smax=Math.max(smax,Math.abs(sc)); }
  smax=Math.min(smax,8);   // clip the score scale so it stays readable
  const PY=v=>tp.y0-(v/pmax)*(tp.y0-tp.y1);
  const SY=v=>{ const mid=(bp.y0+bp.y1)/2; return mid-(Math.max(-smax,Math.min(smax,v))/smax)*(mid-bp.y1); };
  // --- density panel ---
  svg.appendChild(SVG('line',{x1:tp.x0,y1:tp.y0,x2:tp.x1,y2:tp.y0,stroke:'var(--line)'}));
  const t1=SVG('text',{x:tp.x0+4,y:tp.y1+12,'font-size':11,fill:'var(--mute)'}); t1.textContent='density p(x)'; svg.appendChild(t1);
  let dp='M'; for(let i=0;i<=N;i++) dp+=` ${PX(xs[i]).toFixed(1)} ${PY(ps[i]).toFixed(1)}`;
  svg.appendChild(SVG('path',{d:dp,fill:'none',stroke:'var(--yellow)','stroke-width':2.4}));
  // --- score panel ---
  const mid=(bp.y0+bp.y1)/2;
  svg.appendChild(SVG('line',{x1:bp.x0,y1:mid,x2:bp.x1,y2:mid,stroke:'var(--line)'}));
  const t2=SVG('text',{x:bp.x0+4,y:bp.y1+12,'font-size':11,fill:'var(--mute)'}); t2.textContent='score s(x) = d/dx log p(x)'; svg.appendChild(t2);
  const axd=SVG('text',{x:(bp.x0+bp.x1)/2,y:H-6,'text-anchor':'middle','font-size':11,fill:'var(--mute)'}); axd.textContent='x'; svg.appendChild(axd);
  let ds='M'; for(let i=0;i<=N;i++) ds+=` ${PX(xs[i]).toFixed(1)} ${SY(ss[i]).toFixed(1)}`;
  svg.appendChild(SVG('path',{d:ds,fill:'none',stroke:'var(--cyan)','stroke-width':2.2}));
  // mark the two modes (score crosses zero, pointing inward)
  for(const m of mu){ svg.appendChild(SVG('line',{x1:PX(m),y1:tp.y1,x2:PX(m),y2:bp.y0,stroke:'var(--violet)','stroke-width':1,'stroke-dasharray':'3 4'})); }
  // a couple of score arrows on the x-axis showing flow toward density
  for(const x of [-4,-3,0,3,4]){ const sc=score(x,w1,s); const len=Math.max(-1,Math.min(1,sc/3))*26;
    drawArrow(svg,[PX(x),mid+34],[PX(x)+len,mid+34],{color:'var(--green)',markerId:'sc-arr',width:1.6,pad1:0,pad2:6}); }
  out.textContent =
    `mixture: w·N(${mu[0]}, σ²) + (1−w)·N(${mu[1]}, σ²),  w = ${w1.toFixed(2)}, σ = ${s.toFixed(1)}\n`+
    `s(x) = ∇ log p(x) = p'(x)/p(x)  — the normalizer Z is gone (∇ log(p̃/Z) = ∇ log p̃)\n`+
    `green arrows = score direction: they point uphill, toward the nearer mode (s = 0 at each mode/valley)`;
}
w1Sl.addEventListener('input',render);
sgSl.addEventListener('input',render);
render();

const svg=$('#lang-svg'), out=$('#lang-out'), nSl=$('#lg-steps'), nL=$('#lg-steps-lbl'), dtSl=$('#lg-dt'), dtL=$('#lg-dt-lbl'), runBtn=$('#lg-run');
const W=640,H=360, padL=44,padR=20,padT=22,padB=40;
const x0=padL,x1=W-padR,y0=H-padB,y1=padT;
const mu=[-1.8,1.8], s=0.7, w1=0.5;   // fixed target mixture
const A=-6,B=6;
const PX=x=>x0+(x-A)/(B-A)*(x1-x0);
// deterministic RNG (Mulberry32) so the picture is reproducible
function mk(seed){ return function(){ seed|=0; seed=seed+0x6D2B79F5|0; let t=Math.imul(seed^seed>>>15,1|seed); t=t+Math.imul(t^t>>>7,61|t)^t; return ((t^t>>>14)>>>0)/4294967296; }; }
function gauss(rng){ let u=0,v=0; while(u===0)u=rng(); while(v===0)v=rng(); return Math.sqrt(-2*Math.log(u))*Math.cos(2*Math.PI*v); }
function comp(x,m){ return Math.exp(-(x-m)*(x-m)/(2*s*s))/(s*Math.sqrt(2*Math.PI)); }
function dens(x){ return w1*comp(x,mu[0])+(1-w1)*comp(x,mu[1]); }
function dcomp(x,m){ return -(x-m)/(s*s)*comp(x,m); }
function score(x){ const p=dens(x); return p>1e-9 ? (w1*dcomp(x,mu[0])+(1-w1)*dcomp(x,mu[1]))/p : 0; }
function render(){
  svg.innerHTML='';
  const steps=Math.round(+nSl.value), dt=+dtSl.value; nL.textContent=steps+' steps'; dtL.textContent='dt = '+dt.toFixed(3);
  // run M particles from a wide N(0, 3^2) init using only the score
  const M=4000, rng=mk(20240522);
  const xs=new Float64Array(M);
  for(let i=0;i<M;i++) xs[i]=3*gauss(rng);
  for(let k=0;k<steps;k++){ for(let i=0;i<M;i++){ xs[i]+=0.5*score(xs[i])*dt + Math.sqrt(dt)*gauss(rng); } }
  // histogram
  const NB=48; const bins=new Float64Array(NB);
  for(let i=0;i<M;i++){ const x=xs[i]; if(x<A||x>B) continue; const b=Math.min(NB-1,Math.floor((x-A)/(B-A)*NB)); bins[b]++; }
  const bw=(B-A)/NB; let area=0; for(let b=0;b<NB;b++) area+=bins[b]*bw;
  // target density curve for overlay (scale to same vertical units)
  let pmax=1e-6; for(let i=0;i<=200;i++){ pmax=Math.max(pmax,dens(A+(B-A)*i/200)); }
  const hmax=Math.max(pmax, Math.max(...bins)/(M*bw))*1.15;
  const HY=v=>y0-(v/hmax)*(y0-y1);
  // axes
  svg.appendChild(SVG('line',{x1:x0,y1:y0,x2:x1,y2:y0,stroke:'var(--line)'}));
  const axd=SVG('text',{x:(x0+x1)/2,y:H-8,'text-anchor':'middle','font-size':12,fill:'var(--mute)'}); axd.textContent='x'; svg.appendChild(axd);
  // bars
  for(let b=0;b<NB;b++){ const xL=A+b*bw; const h=bins[b]/(M*bw); if(h<=0) continue;
    svg.appendChild(SVG('rect',{x:PX(xL),y:HY(h),width:PX(xL+bw)-PX(xL)-1,height:y0-HY(h),fill:'var(--cyan)','fill-opacity':0.5})); }
  // target curve
  let dp='M'; for(let i=0;i<=240;i++){ const x=A+(B-A)*i/240; dp+=` ${PX(x).toFixed(1)} ${HY(dens(x)).toFixed(1)}`; }
  svg.appendChild(SVG('path',{d:dp,fill:'none',stroke:'var(--yellow)','stroke-width':2.4}));
  function leg(x,y,co,t){ svg.appendChild(SVG('rect',{x,y:y-8,width:14,height:10,fill:co,'fill-opacity':co==='var(--cyan)'?0.5:1})); const tt=SVG('text',{x:x+20,y:y,'font-size':11,fill:'var(--mute)'}); tt.textContent=t; svg.appendChild(tt); }
  leg(x0+10,y1+10,'var(--cyan)','Langevin particles (histogram)');
  leg(x0+10,y1+26,'var(--yellow)','target mixture p(x)');
  // crude TV-style mismatch measure
  let mism=0; for(let b=0;b<NB;b++){ const xc=A+(b+0.5)*bw; mism+=Math.abs(bins[b]/(M*bw)-dens(xc))*bw; }
  out.textContent =
    `target = ½ N(${mu[0]}, ${s}²) + ½ N(${mu[1]}, ${s}²);  ${M} particles from a wide N(0, 3²) start\n`+
    `update: x ← x + ½ s(x) dt + √dt · ε,  using ONLY the score s(x) = ∇ log p(x)\n`+
    `after ${steps} steps:  histogram–target L¹ mismatch ≈ ${mism.toFixed(3)}  ` +
    (steps>=120 ? '— converged to both modes' : '— increase steps to converge');
}
nSl.addEventListener('input',render);
dtSl.addEventListener('input',render);
runBtn.addEventListener('click',render);
render();

const svg=$('#fwd-svg'), out=$('#fwd-out'), tSl=$('#fw-t'), tL=$('#fw-t-lbl');
const W=640,H=360, padL=46,padR=20,padT=24,padB=40;
const x0=padL,x1=W-padR,y0=H-padB,y1=padT;
// data = two-delta-ish mixture of narrow Gaussians; OU forward with constant beta
const mu=[-2.2,2.4], s0=0.45, w1=0.5, beta=1.0;
const A=-6,B=6;
const PX=x=>x0+(x-A)/(B-A)*(x1-x0);
function comp(x,m,s){ return Math.exp(-(x-m)*(x-m)/(2*s*s))/(s*Math.sqrt(2*Math.PI)); }
function render(){
  svg.innerHTML='';
  const t=+tSl.value; tL.textContent='t = '+t.toFixed(2);
  // OU marginal of x_t | x_0: mean sqrt(abar)*x0, var (1-abar) + abar*s0^2 (convolve data with kernel)
  const abar=Math.exp(-beta*t);              // = e^{-\int beta}
  const mean=m=>Math.sqrt(abar)*m;
  const varc=(1-abar)+abar*s0*s0;            // variance of each blurred component
  const sc=Math.sqrt(varc);
  function pt(x){ return w1*comp(x,mean(mu[0]),sc)+(1-w1)*comp(x,mean(mu[1]),sc); }
  function prior(x){ return comp(x,0,1); }   // N(0,1) target of the forward process
  // scale
  let pmax=1e-6; for(let i=0;i<=240;i++){ pmax=Math.max(pmax,pt(A+(B-A)*i/240)); }
  pmax=Math.max(pmax, comp(0,0,1));
  const PY=v=>y0-(v/pmax)*(y0-y1);
  // axes
  svg.appendChild(SVG('line',{x1:x0,y1:y0,x2:x1,y2:y0,stroke:'var(--line)'}));
  const axd=SVG('text',{x:(x0+x1)/2,y:H-8,'text-anchor':'middle','font-size':12,fill:'var(--mute)'}); axd.textContent='x'; svg.appendChild(axd);
  // prior N(0,1) dashed
  let pr='M'; for(let i=0;i<=240;i++){ const x=A+(B-A)*i/240; pr+=` ${PX(x).toFixed(1)} ${PY(prior(x)).toFixed(1)}`; }
  svg.appendChild(SVG('path',{d:pr,fill:'none',stroke:'var(--mute)','stroke-width':1.4,'stroke-dasharray':'5 4'}));
  // perturbed marginal p_t
  let dp='M'; for(let i=0;i<=240;i++){ const x=A+(B-A)*i/240; dp+=` ${PX(x).toFixed(1)} ${PY(pt(x)).toFixed(1)}`; }
  svg.appendChild(SVG('path',{d:dp,fill:'none',stroke:'var(--yellow)','stroke-width':2.6}));
  function leg(x,y,co,t,dash){ const ln=SVG('line',{x1:x,y1:y,x2:x+22,y2:y,stroke:co,'stroke-width':2.4}); if(dash) ln.setAttribute('stroke-dasharray','5 4'); svg.appendChild(ln); const tt=SVG('text',{x:x+28,y:y+4,'font-size':11,fill:'var(--mute)'}); tt.textContent=t; svg.appendChild(tt); }
  leg(x0+10,y1+10,'var(--yellow)','perturbed marginal p_t(x)');
  leg(x0+10,y1+26,'var(--mute)','prior N(0,1)',true);
  out.textContent =
    `forward (VP/OU):  dx = −½β x dt + √β dW,   β = ${beta.toFixed(1)}\n`+
    `x_t | x₀ ~ N( √āₜ·x₀, (1−āₜ)·I ),   āₜ = e^{−∫β} = ${abar.toFixed(3)}\n`+
    `at t = ${t.toFixed(2)}:  mean shrink √āₜ = ${Math.sqrt(abar).toFixed(3)},  comp. std = ${sc.toFixed(3)}  ` +
    (abar<0.05 ? '— essentially pure N(0,1) noise' : '— modes still visible');
}
tSl.addEventListener('input',render);
render();

const svg=$('#rev-svg'), out=$('#rev-out'), tSl=$('#rv-t'), tL=$('#rv-t-lbl'), runBtn=$('#rv-run');
const W=640,H=360, padL=44,padR=20,padT=22,padB=40;
const x0=padL,x1=W-padR,y0=H-padB,y1=padT;
const mu=[-2.2,2.4], s0=0.45, w1=0.5, beta=1.0, T=4.0;
const A=-6,B=6;
const PX=x=>x0+(x-A)/(B-A)*(x1-x0);
function mk(seed){ return function(){ seed|=0; seed=seed+0x6D2B79F5|0; let t=Math.imul(seed^seed>>>15,1|seed); t=t+Math.imul(t^t>>>7,61|t)^t; return ((t^t>>>14)>>>0)/4294967296; }; }
function gauss(rng){ let u=0,v=0; while(u===0)u=rng(); while(v===0)v=rng(); return Math.sqrt(-2*Math.log(u))*Math.cos(2*Math.PI*v); }
function comp(x,m,s){ return Math.exp(-(x-m)*(x-m)/(2*s*s))/(s*Math.sqrt(2*Math.PI)); }
// closed-form score of the perturbed marginal p_t (mixture stays a mixture under linear OU)
function scoreT(x,t){ const abar=Math.exp(-beta*t); const sc=Math.sqrt((1-abar)+abar*s0*s0);
  const m0=Math.sqrt(abar)*mu[0], m1=Math.sqrt(abar)*mu[1];
  const a=w1*comp(x,m0,sc), b=(1-w1)*comp(x,m1,sc); const p=a+b;
  if(p<1e-12) return 0; const dlog=(a*(-(x-m0)/(sc*sc))+b*(-(x-m1)/(sc*sc)))/p; return dlog; }
function densData(x){ return w1*comp(x,mu[0],s0)+(1-w1)*comp(x,mu[1],s0); }
function render(){
  svg.innerHTML='';
  const tStop=+tSl.value; tL.textContent='t = '+tStop.toFixed(2);
  // integrate the reverse SDE from t=T down to tStop, M particles starting at N(0,1)
  const M=4000, K=400, dt=(T)/K, rng=mk(7777);
  const xs=new Float64Array(M); for(let i=0;i<M;i++) xs[i]=gauss(rng);
  let t=T;
  // g(t)^2 = beta (constant), f = -1/2 beta x
  for(let k=0;k<K;k++){ if(t<=tStop+1e-9) break;
    for(let i=0;i<M;i++){ const x=xs[i]; const drift=(-0.5*beta*x) - beta*scoreT(x,t); xs[i]=x - drift*dt + Math.sqrt(beta*dt)*gauss(rng); }
    t-=dt; }
  // histogram of particles at the stopping time
  const NB=48, bins=new Float64Array(NB), bw=(B-A)/NB;
  for(let i=0;i<M;i++){ const x=xs[i]; if(x<A||x>B) continue; bins[Math.min(NB-1,Math.floor((x-A)/(B-A)*NB))]++; }
  // overlay: true p_t at the stopping time
  const abar=Math.exp(-beta*tStop), sc=Math.sqrt((1-abar)+abar*s0*s0);
  function ptrue(x){ return w1*comp(x,Math.sqrt(abar)*mu[0],sc)+(1-w1)*comp(x,Math.sqrt(abar)*mu[1],sc); }
  let pmax=1e-6; for(let i=0;i<=200;i++){ pmax=Math.max(pmax,ptrue(A+(B-A)*i/200)); }
  const hmax=Math.max(pmax, Math.max(...bins)/(M*bw))*1.15;
  const HY=v=>y0-(v/hmax)*(y0-y1);
  svg.appendChild(SVG('line',{x1:x0,y1:y0,x2:x1,y2:y0,stroke:'var(--line)'}));
  const axd=SVG('text',{x:(x0+x1)/2,y:H-8,'text-anchor':'middle','font-size':12,fill:'var(--mute)'}); axd.textContent='x'; svg.appendChild(axd);
  for(let b=0;b<NB;b++){ const xL=A+b*bw; const h=bins[b]/(M*bw); if(h<=0) continue;
    svg.appendChild(SVG('rect',{x:PX(xL),y:HY(h),width:PX(xL+bw)-PX(xL)-1,height:y0-HY(h),fill:'var(--pink)','fill-opacity':0.45})); }
  let dp='M'; for(let i=0;i<=240;i++){ const x=A+(B-A)*i/240; dp+=` ${PX(x).toFixed(1)} ${HY(ptrue(x)).toFixed(1)}`; }
  svg.appendChild(SVG('path',{d:dp,fill:'none',stroke:'var(--yellow)','stroke-width':2.4}));
  function leg(x,y,co,t,bar){ if(bar){ svg.appendChild(SVG('rect',{x,y:y-8,width:14,height:10,fill:co,'fill-opacity':0.45})); } else { svg.appendChild(SVG('line',{x1:x,y1:y-3,x2:x+22,y2:y-3,stroke:co,'stroke-width':2.4})); } const tt=SVG('text',{x:x+(bar?20:28),y:y,'font-size':11,fill:'var(--mute)'}); tt.textContent=t; svg.appendChild(tt); }
  leg(x0+10,y1+10,'var(--pink)','reverse-SDE particles at t',true);
  leg(x0+10,y1+26,'var(--yellow)','true marginal p_t(x)',false);
  out.textContent =
    `reverse SDE:  dx = [ f − g² ∇log p_t ] dt + g dW̄,   f = −½βx,  g² = β = ${beta.toFixed(1)}\n`+
    `start: ${M} samples from the N(0,1) prior at t = T = ${T.toFixed(1)}; integrate backward to t\n`+
    `at t = ${tStop.toFixed(2)}:  particles match the true p_t  ` +
    (tStop<0.05 ? '— fully reconstructed the two-mode data distribution' : '— lower t to finish denoising');
}
tSl.addEventListener('input',render);
runBtn.addEventListener('click',render);
render();

const svg=$('#sm-svg'), out=$('#sm-out'), sgSl=$('#sm-sig'), sgL=$('#sm-sig-lbl'), nSl=$('#sm-n'), nL=$('#sm-n-lbl'), fitBtn=$('#sm-fit');
const W=640,H=360, padL=48,padR=20,padT=22,padB=40;
const x0=padL,x1=W-padR,y0=H-padB,y1=padT;
const mu=[-1.8,1.8], sdata=0.5, w1=0.5;   // clean data mixture
const A=-6,B=6;
const PX=x=>x0+(x-A)/(B-A)*(x1-x0);
function mk(seed){ return function(){ seed|=0; seed=seed+0x6D2B79F5|0; let t=Math.imul(seed^seed>>>15,1|seed); t=t+Math.imul(t^t>>>7,61|t)^t; return ((t^t>>>14)>>>0)/4294967296; }; }
function gauss(rng){ let u=0,v=0; while(u===0)u=rng(); while(v===0)v=rng(); return Math.sqrt(-2*Math.log(u))*Math.cos(2*Math.PI*v); }
function comp(x,m,s){ return Math.exp(-(x-m)*(x-m)/(2*s*s))/(s*Math.sqrt(2*Math.PI)); }
// true score of the sigma-perturbed data: convolve mixture with N(0,sigma^2)
function trueScore(x,sig){ const sc=Math.sqrt(sdata*sdata+sig*sig);
  const a=w1*comp(x,mu[0],sc), b=(1-w1)*comp(x,mu[1],sc); const p=a+b; if(p<1e-12) return 0;
  return (a*(-(x-mu[0])/(sc*sc))+b*(-(x-mu[1])/(sc*sc)))/p; }
function render(){
  svg.innerHTML='';
  const sig=+sgSl.value, n=Math.round(+nSl.value); sgL.textContent='σ = '+sig.toFixed(2); nL.textContent=n+' basis fns';
  // build a denoising-score-matching fit: sample (x, xtilde), regress on a small RBF basis
  // targets are the conditional score -(xtilde - x)/sigma^2 -- pure DSM
  const rng=mk(424242), M=3000;
  const centers=[]; for(let j=0;j<n;j++) centers.push(A+ (B-A)*(j+0.5)/n);
  const h=(B-A)/n*0.9;
  function feat(x){ const f=new Array(n+1); for(let j=0;j<n;j++) f[j]=Math.exp(-((x-centers[j])**2)/(2*h*h)); f[n]=1; return f; }
  // normal equations (ridge) on the DSM objective
  const dimn=n+1; const ATA=[]; for(let i=0;i<dimn;i++){ ATA.push(new Float64Array(dimn)); } const ATb=new Float64Array(dimn);
  for(let i=0;i<M;i++){ // draw clean x from mixture, then noised xtilde
    const which=rng()<w1?0:1; const x=mu[which]+sdata*gauss(rng); const xt=x+sig*gauss(rng);
    const target=-(xt-x)/(sig*sig); const f=feat(xt);
    for(let a=0;a<dimn;a++){ ATb[a]+=f[a]*target; for(let b=0;b<dimn;b++) ATA[a][b]+=f[a]*f[b]; } }
  const lam=1e-2*M; for(let i=0;i<dimn;i++) ATA[i][i]+=lam;
  // solve via Gaussian elimination
  const Aug=[]; for(let i=0;i<dimn;i++){ Aug.push(Float64Array.from([...ATA[i],ATb[i]])); }
  for(let c=0;c<dimn;c++){ let piv=c; for(let r=c+1;r<dimn;r++) if(Math.abs(Aug[r][c])>Math.abs(Aug[piv][c])) piv=r; [Aug[c],Aug[piv]]=[Aug[piv],Aug[c]];
    const d=Aug[c][c]||1e-9; for(let k=c;k<=dimn;k++) Aug[c][k]/=d; for(let r=0;r<dimn;r++){ if(r===c) continue; const fct=Aug[r][c]; for(let k=c;k<=dimn;k++) Aug[r][k]-=fct*Aug[c][k]; } }
  const wgt=new Float64Array(dimn); for(let i=0;i<dimn;i++) wgt[i]=Aug[i][dimn];
  function smodel(x){ const f=feat(x); let s=0; for(let a=0;a<dimn;a++) s+=wgt[a]*f[a]; return s; }
  // plot true vs fitted score
  let smax=1e-6; for(let i=0;i<=200;i++){ const x=A+(B-A)*i/200; smax=Math.max(smax,Math.abs(trueScore(x,sig)),Math.abs(smodel(x))); }
  smax=Math.min(smax,8);
  const mid=(y0+y1)/2; const SY=v=>mid-(Math.max(-smax,Math.min(smax,v))/smax)*(mid-y1);
  svg.appendChild(SVG('line',{x1:x0,y1:mid,x2:x1,y2:mid,stroke:'var(--line)'}));
  const axd=SVG('text',{x:(x0+x1)/2,y:H-8,'text-anchor':'middle','font-size':12,fill:'var(--mute)'}); axd.textContent='x̃ (noised input)'; svg.appendChild(axd);
  let dt='M', dm='M', mse=0, cnt=0;
  for(let i=0;i<=240;i++){ const x=A+(B-A)*i/240; const ts=trueScore(x,sig), ms=smodel(x);
    dt+=` ${PX(x).toFixed(1)} ${SY(ts).toFixed(1)}`; dm+=` ${PX(x).toFixed(1)} ${SY(ms).toFixed(1)}`;
    if(x>-4&&x<4){ mse+=(ts-ms)**2; cnt++; } }
  svg.appendChild(SVG('path',{d:dt,fill:'none',stroke:'var(--yellow)','stroke-width':2.6}));
  svg.appendChild(SVG('path',{d:dm,fill:'none',stroke:'var(--cyan)','stroke-width':2,'stroke-dasharray':'6 4'}));
  function leg(x,y,co,t,dash){ const ln=SVG('line',{x1:x,y1:y,x2:x+22,y2:y,stroke:co,'stroke-width':2.4}); if(dash) ln.setAttribute('stroke-dasharray','6 4'); svg.appendChild(ln); const tt=SVG('text',{x:x+28,y:y+4,'font-size':11,fill:'var(--mute)'}); tt.textContent=t; svg.appendChild(tt); }
  leg(x0+10,y1+10,'var(--yellow)','true score ∇ log p_σ');
  leg(x0+10,y1+26,'var(--cyan)','learned s_θ (DSM)',true);
  out.textContent =
    `DSM objective:  min_θ E‖ s_θ(x̃) − ∇_x̃ log q_σ(x̃|x) ‖²,  q_σ(x̃|x) = N(x, σ²)\n`+
    `conditional target = −(x̃ − x)/σ² = −ε/σ   (⇒ the net predicts the noise ε)\n`+
    `fit with ${n} RBF basis fns:  mean-squared score error on [−4,4] ≈ ${(mse/cnt).toFixed(4)}`;
}
