const svg=$('#pf-svg'), out=$('#pf-out'), kSl=$('#pf-k'), kL=$('#pf-k-lbl'), runBtn=$('#pf-run');
const W=640,H=360, padL=44,padR=20,padT=22,padB=40;
const x0=padL,x1=W-padR,y0=H-padB,y1=padT;
const mu=[-2.2,2.4], s0=0.45, w1=0.5, beta=1.0, T=4.0;
const A=-6,B=6;
const TX=t=>x0+(1-t/T)*(x1-x0);     // time runs T (left) -> 0 (right), generation direction
const XY=x=>y0-((x-A)/(B-A))*(y0-y1);
function mk(seed){ return function(){ seed|=0; seed=seed+0x6D2B79F5|0; let t=Math.imul(seed^seed>>>15,1|seed); t=t+Math.imul(t^t>>>7,61|t)^t; return ((t^t>>>14)>>>0)/4294967296; }; }
function gauss(rng){ let u=0,v=0; while(u===0)u=rng(); while(v===0)v=rng(); return Math.sqrt(-2*Math.log(u))*Math.cos(2*Math.PI*v); }
function comp(x,m,s){ return Math.exp(-(x-m)*(x-m)/(2*s*s))/(s*Math.sqrt(2*Math.PI)); }
function scoreT(x,t){ const abar=Math.exp(-beta*t); const sc=Math.sqrt((1-abar)+abar*s0*s0);
  const m0=Math.sqrt(abar)*mu[0], m1=Math.sqrt(abar)*mu[1];
  const a=w1*comp(x,m0,sc), b=(1-w1)*comp(x,m1,sc); const p=a+b; if(p<1e-12) return 0;
  return (a*(-(x-m0)/(sc*sc))+b*(-(x-m1)/(sc*sc)))/p; }
function render(){
  svg.innerHTML='';
  const nTraj=Math.round(+kSl.value); kL.textContent=nTraj+' paths each';
  const K=300, dt=T/K, rng=mk(31337);
  // shared starting points at t=T so SDE & ODE paths start identically
  const starts=[]; for(let i=0;i<nTraj;i++) starts.push(1.0*gauss(rng));
  // axes / frame
  svg.appendChild(SVG('rect',{x:x0,y:y1,width:x1-x0,height:y0-y1,fill:'none',stroke:'var(--line)'}));
  const axt=SVG('text',{x:(x0+x1)/2,y:H-8,'text-anchor':'middle','font-size':11,fill:'var(--mute)'}); axt.textContent='time:  noise (t=T, left)  →  data (t=0, right)'; svg.appendChild(axt);
  const axx=SVG('text',{x:14,y:(y0+y1)/2,'text-anchor':'middle','font-size':11,fill:'var(--mute)',transform:`rotate(-90 14 ${(y0+y1)/2})`}); axx.textContent='x'; svg.appendChild(axx);
  // mark the two data modes on the right edge
  for(const m of mu){ svg.appendChild(SVG('line',{x1:x0,y1:XY(m),x2:x1,y2:XY(m),stroke:'var(--violet)','stroke-width':1,'stroke-dasharray':'2 5'})); }
  const endsSDE=[], endsODE=[];
  // SDE paths (pink)
  for(let i=0;i<nTraj;i++){ let x=starts[i], t=T; let d=`M ${TX(t).toFixed(1)} ${XY(x).toFixed(1)}`;
    for(let k=0;k<K;k++){ const drift=(-0.5*beta*x)-beta*scoreT(x,t); x=x-drift*dt+Math.sqrt(beta*dt)*gauss(rng); t-=dt; d+=` L ${TX(Math.max(0,t)).toFixed(1)} ${XY(x).toFixed(1)}`; }
    endsSDE.push(x); svg.appendChild(SVG('path',{d,fill:'none',stroke:'var(--pink)','stroke-width':1,'stroke-opacity':0.7})); }
  // PF-ODE paths (cyan) -- deterministic, half-weight score, no noise
  for(let i=0;i<nTraj;i++){ let x=starts[i], t=T; let d=`M ${TX(t).toFixed(1)} ${XY(x).toFixed(1)}`;
    for(let k=0;k<K;k++){ const vel=(-0.5*beta*x)-0.5*beta*scoreT(x,t); x=x-vel*dt; t-=dt; d+=` L ${TX(Math.max(0,t)).toFixed(1)} ${XY(x).toFixed(1)}`; }
    endsODE.push(x); svg.appendChild(SVG('path',{d,fill:'none',stroke:'var(--cyan)','stroke-width':1.4})); }
  function leg(x,y,co,t){ svg.appendChild(SVG('line',{x1:x,y1:y,x2:x+22,y2:y,stroke:co,'stroke-width':2.2})); const tt=SVG('text',{x:x+28,y:y+4,'font-size':11,fill:'var(--mute)'}); tt.textContent=t; svg.appendChild(tt); }
  leg(x0+10,y1+14,'var(--pink)','reverse SDE (stochastic)');
  leg(x0+10,y1+30,'var(--cyan)','PF ODE (deterministic)');
  function frac(ends){ let n=0; for(const e of ends) if(e>0) n++; return n/ends.length; }
  out.textContent =
    `reverse SDE:  dx = [f − g²∇log p_t] dt + g dW̄    (noisy paths)\n`+
    `PF ODE:       dx = [f − ½ g²∇log p_t] dt          (smooth, deterministic paths)\n`+
    `same start (t=T), DIFFERENT paths, SAME endpoint law:  +mode share — SDE ${(frac(endsSDE)*100).toFixed(0)}%, ODE ${(frac(endsODE)*100).toFixed(0)}%`;
}
kSl.addEventListener('input',render);
runBtn.addEventListener('click',render);
render();
